components.css:
.ds-button-primary {
  display: inline-flex;
  align-items: center;
  min-height: 46px;
  line-height: 1.3;
  padding: 0.6rem 1.3rem;
  border-radius: var(--radius);
  font-size: 0.92rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  text-decoration: none;
  transition: background-color 0.15s ease-out, border-color 0.15s ease-out;
}
.ds-button-primary {
  margin: 0;
  transform: none;
}
.ds-button-primary:active {
  margin: 0;
  transform: none;
}
.ds-button-primary {
  background: var(--lime);
  color: var(--ink);
  border: 1px solid var(--lime);
}
.ds-button-primary:hover {
  background: var(--lime-bright);
  border-color: var(--lime-deep);
  color: var(--ink);
}
.ds-button-primary:focus-visible {outline:2px solid var(--lime-deep);outline-offset:3px;}
.ds-button-primary {font-family:var(--font-sans);}

.ds-button-secondary {
  display: inline-flex;
  align-items: center;
  min-height: 46px;
  line-height: 1.3;
  padding: 0.6rem 1.3rem;
  border-radius: var(--radius);
  font-size: 0.92rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  text-decoration: none;
  transition: background-color 0.15s ease-out, border-color 0.15s ease-out;
}
.ds-button-secondary {
  background: var(--panel);
  color: var(--ink);
  border: 1px solid var(--rule-strong);
}
.ds-button-secondary:hover {
  background: var(--panel);
  border-color: var(--ink);
  color: var(--ink);
}
.ds-button-secondary:focus-visible {outline:2px solid var(--lime-deep);outline-offset:3px;}
.ds-button-secondary {font-family:var(--font-sans);}

.ds-nav-link {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  color: var(--muted);
  font-size: 0.92rem;
  font-weight: 500;
  text-decoration: none;
}
.ds-nav-link:hover {
  color: var(--ink);
  background: transparent;
}
.ds-active {
  color: var(--ink);
  font-weight: 500;
  border-bottom: 2px solid var(--lime);
  padding-bottom: 2px;
}
.ds-nav {display:flex;gap:22px;font-family:var(--font-sans);}.ds-nav-link:focus-visible {outline:2px solid var(--lime-deep);outline-offset:3px;}

.ds-chip {
  border: 1px solid var(--rule);
  border-radius: 999px;
  padding: 5px 11px;
  color: var(--muted);
  background: var(--panel);
  font-family: var(--font-mono);
  font-size: 0.74rem;
  letter-spacing: 0.04em;
  line-height: 1.3;
  text-decoration: none;
}
.ds-chip:hover {
  color: var(--ink);
  background: var(--lime-wash);
  border-color: var(--lime);
}
.ds-chip {display:inline-block;}.ds-chip:focus-visible {outline:2px solid var(--lime-deep);outline-offset:3px;}

.ds-panel {
  padding: 20px 22px;
  border: 1px solid var(--rule);
  border-radius: var(--radius);
  background: var(--panel);
  transition: border-color 0.15s ease-out;
}
.ds-panel:hover {
  border-color: var(--rule-strong);
}
.ds-panel h3 {
  margin: 0 0 4px;
  font-size: 1.3rem;
  line-height: 1.15;
  letter-spacing: -0.02em;
}
.ds-panel h3 a {
  text-decoration: none;
}
.ds-panel h3 a:hover {
  background: transparent;
  text-decoration: underline;
  text-decoration-color: var(--lime);
}
.ds-panel p {
  max-width: 62ch;
  margin: 0;
  color: var(--muted);
  font-size: 0.97rem;
  line-height: 1.55;
}
.ds-panel p a {
  text-decoration-thickness: 1px;
}
.ds-panel {font-family:var(--font-sans);}.ds-panel h3 {font-family:var(--font-serif);font-weight:500;color:var(--ink);}.ds-panel a {color:var(--ink);}.ds-panel a:focus-visible {outline:2px solid var(--lime-deep);outline-offset:3px;}
